-- Step 1 of 4 for orders.public_id. Adds the column with no default and no NOT NULL: both are
-- catalog-only changes, so the 80M-row table is not rewritten. The default is set afterwards so that
-- new rows get a value while existing rows stay NULL until the backfill (0005) fills them in.
-- lock_timeout: if the ACCESS EXCLUSIVE lock is queued behind a long query, fail fast instead of
-- stalling every query on orders behind it. A timeout just means re-run the deploy.
SET lock_timeout = '2s';

ALTER TABLE orders ADD COLUMN public_id uuid;
ALTER TABLE orders ALTER COLUMN public_id SET DEFAULT gen_random_uuid();

